CREATE TABLE IF NOT EXISTS machine_provider_limits(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),active_limit integer NOT NULL DEFAULT 1000 CHECK(active_limit BETWEEN 0 AND 100000),starts_per_minute_limit integer NOT NULL DEFAULT 1000 CHECK(starts_per_minute_limit BETWEEN 0 AND 100000),starts_per_hour_limit integer NOT NULL DEFAULT 10000 CHECK(starts_per_hour_limit BETWEEN 0 AND 1000000),starts_per_day_limit integer NOT NULL DEFAULT 100000 CHECK(starts_per_day_limit BETWEEN 0 AND 10000000),cooldown_until timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE machine_provider_limits ADD COLUMN IF NOT EXISTS cooldown_until timestamptz;
INSERT INTO machine_provider_limits(singleton) VALUES(true) ON CONFLICT(singleton) DO NOTHING;
CREATE TABLE IF NOT EXISTS machine_admission_requests(id uuid PRIMARY KEY,owner_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,companion_id uuid NOT NULL REFERENCES companions(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('configuration','resume')),fingerprint text NOT NULL,state text NOT NULL CHECK(state IN ('queued','admitted','cancelling','cancelled','completed','refused')),waiting_reason text,requested_at timestamptz NOT NULL DEFAULT now(),admitted_at timestamptz,start_counted boolean NOT NULL DEFAULT false,cancelled_at timestamptz,released_at timestamptz,UNIQUE(owner_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS one_open_machine_admission_per_companion ON machine_admission_requests(companion_id) WHERE state IN ('queued','admitted','cancelling');
CREATE INDEX IF NOT EXISTS machine_admission_recent_starts ON machine_admission_requests(admitted_at) WHERE start_counted AND admitted_at IS NOT NULL;
ALTER TABLE companions ADD COLUMN IF NOT EXISTS machine_activity_at timestamptz;
ALTER TABLE companions ADD COLUMN IF NOT EXISTS keep_alive_until timestamptz;
